"Летопись пока пуста: Орден ещё не собрал ни одной грани.":"A crônica ainda está vazia: a Ordem ainda não reuniu nenhuma face.",
"Каждый осколок Алатыря, найденный любым Ловчим, — в разломах и у хранителей-старейшин Капищ, — ложится в общий камень Ордена. Собрана грань — дорога в её мир распутана: {0} дня духи этой мифологии встречаются в {1} раза чаще, у всех Ловчих разом. Собраны все грани сезона — приходит Кощей: {2} дней он ждёт во всех Разломах мира, а потом раскалывает камень. Из трещины выходит новая мифология, начинается новый сезон — и в Лиге тоже. В новом сезоне у камня на одну грань больше.":"Cada fragmento de Alatyr encontrado por qualquer Caçador — nas fendas e com os guardiões anciãos dos Kapishche — vai para a pedra comum da Ordem. Quando uma face é reunida, o caminho para o seu mundo se desemaranha: por {0} dias os espíritos dessa mitologia aparecem {1} vezes mais, para todos os Caçadores ao mesmo tempo. Quando todas as faces da temporada são reunidas, chega Koschei: por {2} dias ele espera em todas as Fendas do mundo e depois parte a pedra. Da rachadura sai uma nova mitologia e começa uma nova temporada — na Liga também. Na nova temporada a pedra tem uma face a mais.",
