"Писать можно с {0} уровня":"Escrever a partir do nível {0}",
"Отправить":"Enviar",
"Общий разговор Ловчих.":"Conversa geral dos Caçadores.",
"Торговля: договаривайтесь о сделках — сами сделки идут через Аукцион.":"Comércio: combinem negócios aqui — as trocas em si acontecem pelo Leilão.",
"Ищите команду для Разломов: пишите код комнаты и место.":"Procurem equipe para Fendas: escrevam o código da sala e o local.",
"Вопросы новичков и советы бывалых.":"Perguntas de novatos e dicas de veteranos.",
"Канал твоего клана — его видят только свои.":"Canal do seu clã — só os membros veem.",
"Сегодня":"Hoje",
"Вчера":"Ontem",
"Ссылки запрещены, грубость скрывается.":"Links são proibidos, grosserias ficam ocultas.",
"Правила чата":"Regras do chat",
"Скрытых Ловчих: {0} · Вернуть":"Caçadores ocultos: {0} · Mostrar",
"ур. {0}":"nv. {0}",
"Здесь пока тихо":"Tudo quieto por aqui",
"Напиши первым — тебя увидят все Ловчие твоего клана.":"Escreva primeiro — todos os Caçadores do seu clã vão ver.",
"Напиши первым — тебя увидят все Ловчие Ордена.":"Escreva primeiro — todos os Caçadores da Ordem vão ver.",
"Новые сообщения: {0}":"Novas mensagens: {0}",
"Пожаловаться?":"Denunciar?",
"На сообщение Ловчего «{0}». После трёх жалоб от разных Ловчих оно скрывается для всех.":"A mensagem do Caçador “{0}”. Após três denúncias de Caçadores diferentes, ela fica oculta para todos.",
"Пожаловаться":"Denunciar",
"Жалоба отправлена — спасибо":"Denúncia enviada — obrigado",
"Скрыть сообщения?":"Ocultar mensagens?",
"Сообщения Ловчего «{0}» перестанут показываться на этом телефоне. Вернуть можно в любой момент — строкой «Скрытых Ловчих» вверху чата.":"As mensagens do Caçador “{0}” deixarão de aparecer neste celular. Dá para desfazer a qualquer momento — pela linha “Caçadores ocultos” no topo do chat.",
"Скрыть":"Ocultar",
"Скрыто. Вернуть — «Скрытых Ловчих» вверху чата":"Oculto. Para desfazer — “Caçadores ocultos” no topo do chat",
"твой клан":"seu clã",
"Клан «?»":"Clã “?”",
"откроется в сезоне {0}":"abre na temporada {0}",
"Клан мифологии следующего сезона. Он откроется, когда Орден соберёт Алатырь-камень и Кощей снова расколет его.":"O clã da mitologia da próxima temporada. Ele abre quando a Ordem reunir a pedra Alatyr e Koschei parti-la de novo.",
"Клан можно выбрать с {0} уровня":"Dá para escolher um clã a partir do nível {0}",
"Выбери клан":"Escolha um clã",
"У каждой мифологии Перепутицы — свой клан Ордена. Кланы держат Капища: поставь своего духа защитником — и Капище окрасится цветом твоего клана, а тебе каждый день будет приходить дань. Выбор — навсегда.":"Cada mitologia do Grande Emaranhado tem seu próprio clã da Ordem. Os clãs defendem os Kapishches: coloque seu espírito como defensor — o Kapishche ganha a cor do seu clã, e você recebe tributo todo dia. A escolha é para sempre.",
"Позже":"Depois",
"Выбор — навсегда: сменить клан потом нельзя.":"A escolha é para sempre: depois não dá para trocar de clã.",
"Переход бесплатный и единственный. Защитники достоят свой срок на Капищах прежнего клана, чат — уже нового.":"A troca é gratuita e única. Seus defensores cumprirão o turno nos Kapishches do clã antigo; o chat já será o do novo.",
"Мифология: {0}":"Mitologia: {0}",
"Звание: {0}":"Posto: {0}",
"На святилищах своей мифологии ({0}) защитники клана собирают дань {1}.":"Nos santuários da própria mitologia ({0}), os defensores do clã recolhem tributo {1}.",
"Перейти":"Mudar",
"Вступить":"Entrar",
"Ты в «{0}»! Побеждай на Капищах и ставь защитников.":"Você está em “{0}”! Vença nos Kapishches e coloque defensores.",
"Теперь ты в «{0}». Добро пожаловать, {1}!":"Agora você está em “{0}”. Boas-vindas, {1}!",
"Дружины стали кланами":"As druzhinas viraram clãs",
"Орден собрал Ловчих всех земель: теперь у каждой мифологии свой клан, а с каждым новым сезоном Алатыря приходит ещё один.":"A Ordem reuniu Caçadores de todas as terras: agora cada mitologia tem seu próprio clã, e cada nova temporada de Alatyr traz mais um.",
"Твоя дружина теперь —":"Sua druzhina agora é",
"Защитники на Капищах и чат клана остались с тобой.":"Seus defensores nos Kapishches e o chat do clã continuam com você.",
"Один раз можно бесплатно перейти в любой открытый клан. Выбери его — или останься. Перейти можно и позже, на экране клана.":"Uma vez, você pode mudar de graça para qualquer clã aberto. Escolha um — ou fique. Também dá para mudar depois, na tela do clã.",
"Остаться":"Ficar",
"Кого поставить защитником?":"Quem vai ser o defensor?",
"Дух останется у тебя: на Капище встанет его отражение. Пока он стоит, раз в день приходит дань — ✦ {0} и оберег.":"O espírito continua com você: no Kapishche fica o reflexo dele. Enquanto ele estiver lá, uma vez por dia chega tributo — ✦ {0} e um talismã.",
"Отражение стоит до {0} суток: первые {1} ч в полной силе, потом устаёт и слабеет, а затем возвращается домой. Защитники — не больше чем на {2} Капищах.":"O reflexo fica até {0} dias: as primeiras {1} h com força total, depois se cansa e enfraquece, e então volta para casa. Defensores — em no máximo {2} Kapishches.",
"Это святилище мифологии твоего клана — дань здесь {0}.":"Este é um santuário da mitologia do seu clã — aqui o tributo é {0}.",
"Защитник встал на Капище «{0}» — оно под знаменем «{1}»":"O defensor assumiu o Kapishche “{0}” — agora sob a bandeira de “{1}”",
