"устал: уровень −{0}% · домой через {1} ч":"cansado: nível −{0}% · volta em {1} h",
"в полной силе ещё {0} ч":"força total por mais {0} h",
"святилище твоей мифологии · дань {0}":"santuário da sua mitologia · tributo {0}",
"Капища рядом (≈5 км)":"Kapishches por perto (≈5 km)",
"Капища по всему свету":"Kapishches no mundo todo",
"Мои защитники":"Meus defensores",
"{0} из {1}":"{0} de {1}",
"Пока нигде. Победи на Капище и поставь защитника — каждый день будет приходить дань.":"Nenhum ainda. Vença em um Kapishche e coloque um defensor — o tributo chega todo dia.",
"Дань — ✦ {0}, оберег и {1} {2} в день за каждое Капище, где твой защитник отстоял хотя бы {3} ч. Защитник стоит до {4} суток и понемногу устаёт; если соперники его победят или срок выйдет, он вернётся с искрами за время на посту. Часть Капищ — вольные: их не держит ни один клан.":"Tributo — ✦ {0}, um talismã e {1} {2} por dia por cada Kapishche onde seu defensor ficou pelo menos {3} h. O defensor fica até {4} dias e vai se cansando; se os rivais o vencerem ou o prazo acabar, ele volta com faíscas pelo tempo no posto. Alguns Kapishches são livres: nenhum clã os domina.",
"На святилищах мифологии твоего клана искры и обереги дани — {0}.":"Nos santuários da mitologia do seu clã, as faíscas e talismãs do tributo são {0}.",
