"Оберег":"Talismã",
"Узелок с заговорённой травой. Бросай в духа, чтобы поймать.":"Uma trouxinha de erva encantada. Jogue no espírito para capturá-lo.",
"Серебряный оберег":"Talismã de prata",
"Серебро держит духов крепче. Шанс поимки ×1,5.":"A prata segura os espíritos com mais força. Chance de captura ×1,5.",
"Золотой оберег":"Talismã de ouro",
"Лучший оберег Ордена. Шанс поимки ×2.":"O melhor talismã da Ordem. Chance de captura ×2.",
"Духи обожают мёд. Успокаивает духа: шанс поимки ×1,5 на один бросок.":"Os espíritos adoram mel. Acalma o espírito: chance de captura ×1,5 em um arremesso.",
"Подорожник":"Tanchagem",
"Лист к ране — и полегчало. Возвращает духу четверть здоровья.":"Uma folha na ferida — e já alivia. Devolve um quarto da vida do espírito.",
"Целебный отвар":"Poção curativa",
"Травы Велеса, сваренные в родниковой воде. Возвращает духу 60% здоровья.":"Ervas de Veles fervidas em água de fonte. Devolve 60% da vida do espírito.",
"Мёртвая вода":"Myortvaya Voda",
"Редкая сказочная вода, что сращивает самые тяжкие раны. Дух без сил поднимется на 4 часа раньше. Живых не лечит.":"Rara água de conto de fadas que fecha as feridas mais graves. Um espírito exausto se levanta 4 horas antes. Não cura quem ainda está de pé.",
"Живая вода":"Zhivaya Voda",
"Возвращает духу половину здоровья, а в разломе — лечит прямо в бою. Духа без сил не поднимет.":"Devolve metade da vida ao espírito, e na fenda cura no meio da batalha. Não levanta um espírito exausto.",
"Ладан":"Incenso",
"Дымок приманивает духов: 30 минут их вокруг вдвое больше.":"A fumacinha atrai espíritos: por 30 minutos, o dobro deles ao seu redor.",
"Дальний пропуск":"Passe remoto",
"Грамота Ордена: закрыть Разлом до 5 км от тебя, не подходя к нему. Один Орден дарит каждый день.":"Carta da Ordem: feche uma Fenda a até 5 km de você sem chegar perto. A Ordem dá um por dia.",
"Кольцо Ордена с воронкой дорог: шагни в любое место Атласа мира сразу, не дожидаясь перезарядки. Одни Врата дарят на седьмой день серии.":"Um anel da Ordem com um redemoinho de caminhos: vá a qualquer lugar do Atlas do mundo na hora, sem esperar a recarga. Um vem de presente no sétimo dia da sequência.",
"Настой опыта":"Chá de XP",
"Медовый настой на травах Велеса: сутки опыта на четверть больше.":"Chá de mel com ervas de Veles: por um dia, um quarto a mais de XP.",
"Подарок":"Presente",
"Узелок для друга: обереги, мёд, иногда кокон. Отправляется в «Меню → Друзья», раз в день каждому.":"Uma trouxinha para um amigo: talismãs, mel, às vezes um casulo. Envie em “Menu → Amigos”, uma vez por dia para cada um.",
