"Преврати одного духа":"Evolua um espírito",
"Закрой разлом":"Feche uma fenda",
"Сфотографируй духа во время встречи":"Fotografe um espírito durante um encontro",
"Преврати духа":"Evolua um espírito",
"Победи хранителя капища":"Vença o guardião de um Kapishche",
"Выведи духа из кокона":"Choque um espírito de um casulo",
"Освободи родник от прислужников Нави":"Liberte uma fonte dos servos da Nav",
"Миров духов всегда было много — у каждого народа свой: Навь у славян, царство Аида у греков, Асгард у скандинавов, холмы сидов у кельтов, Дуат у египтян, Небеса у китайцев, Миктлан у ацтеков. На местах их держал <b>Алатырь</b> — бел-горюч камень в середине всех миров. Каждые врата вели в свою землю, и духи не путали дорог.":"Sempre houve muitos mundos de espíritos — cada povo tinha o seu: a Nav dos eslavos, o reino do Hades dos gregos, Asgard dos escandinavos, as colinas dos sídhe dos celtas, o Duat dos egípcios, os Céus dos chineses, Mictlán dos astecas. Quem os mantinha no lugar era <b>Alatyr</b>, a pedra branca ardente no centro de todos os mundos. Cada portão levava à sua própria terra, e os espíritos não confundiam os caminhos.",
"Однажды осенней ночью Кощей Бессмертный решил спрятать свою смерть понадёжнее — прямо в сердце Алатыря. Камень треснул и раскололся. Все врата распахнулись разом, дороги между мирами спутались в клубок, и духи и боги семи мифологий высыпали в наш мир — кто куда. Эту ночь назвали <b>Перепутицей</b>. Кощей уверяет, что камень треснул сам, но Локи и Сунь Укун при этих словах почему-то хихикают.":"Numa noite de outono, Koschei, o Imortal, resolveu esconder sua morte num lugar mais seguro — bem no coração de Alatyr. A pedra rachou e se partiu. Todos os portões se abriram de uma vez, os caminhos entre os mundos se enrolaram num novelo, e os espíritos e deuses de sete mitologias se espalharam pelo nosso mundo, cada um para um lado. Essa noite ficou conhecida como <b>o Grande Emaranhado</b>. Koschei jura que a pedra rachou sozinha, mas Loki e Sun Wukong, sabe-se lá por quê, dão risadinhas quando ele diz isso.",
"Теперь Гиппокамп плещется в московском фонтане, Леший гуляет по токийскому парку, а Ниссе греет котов в подъездах Каира. Любого духа можно встретить в любом уголке земли. Разломы — трещины от расколотого камня — открываются в каждом городе, а боги ставят святилища там, где осели: Капище по соседству с Пагодой, Храм через улицу от Пирамиды. Город рождает и своих, новых духов: Вайфайку, Трамвайника, Фонарника.":"Agora um Hipocampo chapinha numa fonte de Moscou, um Leshy passeia por um parque de Tóquio e um Nisse aquece gatos nas escadarias do Cairo. Qualquer espírito pode ser encontrado em qualquer canto da Terra. As fendas — rachaduras deixadas pela pedra partida — se abrem em todas as cidades, e os deuses erguem santuários onde se instalaram: um Kapishche ao lado de um Pagode, um Templo do outro lado da rua de uma Pirâmide. A cidade também dá à luz seus próprios espíritos novos: Vayfayka, Tramvaynik, Fonarnik.",
"Первыми с гостями поладили не учёные, а бабушки со своими оберегами: оказалось, оберег, сделанный с заботой, успокаивает любого духа, откуда бы тот ни был. Так появился <b>Орден Оберега</b> — союз Ловчих всех земель. Твоя задача — находить духов, ловить их оберегами, черпать силу из родников, закрывать разломы и собирать осколки Алатыря. Кто знает — может, однажды их хватит, чтобы распутать дороги домой.":"Os primeiros a se dar bem com os recém-chegados não foram os cientistas, e sim as avós com seus talismãs: descobriu-se que um talismã feito com carinho acalma qualquer espírito, venha de onde vier. Assim surgiu a <b>Ordem do Talismã</b> — uma união de Caçadores de todas as terras. Sua missão: encontrar espíritos, capturá-los com talismãs, colher força das fontes, fechar fendas e juntar fragmentos de Alatyr. Quem sabe — talvez um dia eles bastem para desembaraçar os caminhos de volta para casa.",
