"Наследники княжеских дружин под знаком сокола-Рарога. Когда Кощей расколол Алатырь, они первыми встали у Капищ и держат Навь громом Перуна.":"Herdeiros das tropas dos príncipes sob o signo de Rarog, o falcão. Quando Koschei partiu Alatyr, foram os primeiros a se postar nos Kapishches e seguram a Nav com o trovão de Perun.",
