"Друиды и воины священных рощ под рукой медведицы Артио. Братство держит каменные круги, чтобы холмы сидов не распахнулись навсегда.":"Druidas e guerreiros dos bosques sagrados sob a pata de Ártio, a ursa. A irmandade guarda os círculos de pedras para que as colinas dos sídhe não se escancarem para sempre.",
