"Купальская ночь":"Noite de Kupala",
"Цветёт папоротник: Купалинка повсюду, духи Огня, Воды и Леса чаще, ночью сияющие — вдвое чаще.":"A samambaia floresce: Kupalinka por toda parte, espíritos de Fogo, Água e Floresta aparecem mais, e à noite os brilhantes — duas vezes mais.",
"Покров":"Pokrov",
"Первые туманы и иней: духи Ветра и Воды встречаются чаще, Листопадница — повсюду, в родниках больше добычи.":"Primeiras névoas e geadas: espíritos de Vento e Água aparecem mais, Listopadnitsa por toda parte, e as fontes rendem mais.",
"Велесова ночь":"Noite de Veles",
"Граница миров тоньше всего: духи Тени втрое чаще, в великих разломах ждёт Кощей, сияющие Тени вдвое чаще.":"A fronteira entre os mundos está no ponto mais fino: espíritos de Sombra três vezes mais, Koschei espera nas grandes fendas, Sombras brilhantes duas vezes mais.",
"Этот родник теперь принадлежит Нави!":"Esta fonte agora pertence à Nav!",
"Твои духи будут служить Кощею!":"Seus espíritos vão servir a Koschei!",
