"Победи хранителей капищ":"Vença guardiões de Kapishches",
"Победи хранителей капищ: {0}":"Vença guardiões de Kapishches: {0}",
"Первый дух":"O primeiro espírito",
"Твои духи":"Seus espíritos",
"Родники":"Fontes",
"Рядом появился дух — видишь светящийся круг на карте? <b>Коснись духа</b>, а потом <b>смахни оберег вверх</b>, прямо в него.":"Um espírito apareceu por perto — está vendo o círculo brilhante no mapa? <b>Toque no espírito</b> e depois <b>deslize o talismã para cima</b>, direto nele.",
"Второй учебный дух рядом. Кольцо вокруг духа сжимается: бросай, когда оно <b>маленькое</b>, — выйдет «Отлично!». Зелёное кольцо — дух покладистый, красное — упрямый.":"O segundo espírito de treino está por perto. O anel em volta do espírito encolhe: jogue quando ele estiver <b>pequeno</b> — vai sair “Ótimo!”. Anel verde — espírito dócil, vermelho — teimoso.",
"Это меню — здесь все разделы. Пока открыто не всё: разделы откроются по ходу обучения, подсвеченный — следующий.":"Este é o menu — aqui estão todas as seções. Ainda não está tudo aberto: as seções abrem ao longo do tutorial; a destacada é a próxima.",
"Каждый пойманный дух — твой. Открой <b>меню</b> — золотой оберег внизу экрана.":"Cada espírito capturado é seu. Abra o <b>menu</b> — o talismã dourado na parte de baixo da tela.",
"Это твоя коллекция — все пойманные духи. Сверху — сортировка по силе, новизне и имени и фильтр по стихиям.":"Esta é a sua coleção — todos os espíritos capturados. No topo: ordenar por poder, novidade e nome, e filtrar por elemento.",
"Это разделы Ордена. Открой <b>«Духи»</b> — там твоя коллекция.":"Estas são as seções da Ordem. Abra <b>“Espíritos”</b> — lá está a sua coleção.",
"Это карточка духа: сила, стихия, приёмы и семейство. Ниже — кнопки «Усилить» и «Превратить», а ещё можно сделать духа спутником.":"Este é o cartão do espírito: poder, elemento, golpes e família. Abaixo, os botões “Fortalecer” e “Evoluir”, e você também pode tornar o espírito seu parceiro.",
"Коснись любого духа, чтобы открыть его <b>карточку</b>.":"Toque em qualquer espírito para abrir o <b>cartão</b> dele.",
"На карточке — сила духа. Нажми <b>«Усилить»</b>: за искры и эссенцию дух станет сильнее. Эссенцию приносят поимки духов того же семейства.":"No cartão está o poder do espírito. Toque em <b>“Fortalecer”</b>: com faíscas e essência ele fica mais forte. A essência vem de capturas de espíritos da mesma família.",
"Бестиарий — все виды духов. Пойманные видны целиком, встреченные — тенью. Коснись вида, чтобы прочитать о нём.":"O bestiário tem todas as espécies de espíritos. As capturadas aparecem inteiras, as vistas — como sombra. Toque numa espécie para ler sobre ela.",
"Теперь загляни в <b>«Бестиарий»</b> (меню) — там все виды духов. Сколько найдёшь ты?":"Agora dê uma olhada no <b>“Bestiário”</b> (menu) — lá estão todas as espécies. Quantas você vai encontrar?",
"Обереги пополняют <b>родники</b> — синие колодцы у памятников, фонтанов и храмов. Дойди до ближайшего джойстиком по <b>стрелке вверху</b> и коснись его. Если рядом нет — прогуляйся по карте.":"Os talismãs são repostos nas <b>fontes</b> — poços azuis perto de monumentos, chafarizes e templos. Vá até a mais próxima com o joystick seguindo a <b>seta no topo</b> e toque nela. Se não houver nenhuma por perto, dê uma volta pelo mapa.",
"Сумка: обереги, мёд, живая вода и ладан. Сверху видно, сколько ещё поместится; лишнее можно выбросить.":"Bolsa: talismãs, mel, Zhivaya Voda e incenso. No topo aparece quanto ainda cabe; o excesso pode ser descartado.",
"Добыча уже в <b>Сумке</b>. Открой меню → «Сумка» и посмотри, что у тебя есть.":"O espólio já está na <b>Bolsa</b>. Abra menu → “Bolsa” e veja o que você tem.",
"Коконы греются шагами — одновременно можно греть три. Готовый кокон вылупится одним касанием. А твой первый дух идёт рядом — это спутник: в пути он находит эссенцию.":"Os casulos são chocados com passos — dá para chocar três ao mesmo tempo. Um casulo pronto eclode com um toque. E seu primeiro espírito anda ao seu lado — é seu parceiro: pelo caminho, ele encontra essência.",
"Открой меню → <b>«Коконы»</b>. Первый кокон уже греется — пройди 2 км, и он вылупится.":"Abra menu → <b>“Casulos”</b>. O primeiro casulo já está sendo chocado — caminhe 2 km e ele vai eclodir.",
"Здесь задания дня — они обновляются в полночь. А родники иногда дают поручения: выполнишь — встретишь особого духа.":"Aqui estão as missões do dia — elas renovam à meia-noite. E as fontes às vezes dão tarefas: cumpra e você vai encontrar um espírito especial.",
"Открой <b>«Задания»</b> — там задания дня.":"Abra <b>“Missões”</b> — lá estão as missões do dia.",
"Путь Ловчего: что откроется на каждом уровне и какие награды ждут. Звания растут: Послушник, Ловчий, Следопыт, Ведун, Хранитель.":"Caminho do Caçador: o que se abre em cada nível e quais recompensas esperam. Os títulos sobem: Noviço, Caçador, Rastreador, Sábio, Guardião.",
"И последнее: открой <b>«Путь»</b> в меню — там видно, что откроется на каждом уровне Ловчего.":"E por último: abra o <b>“Caminho”</b> no menu — lá você vê o que se abre em cada nível de Caçador.",
