"Победа засчитана, но пока шёл бой, на Капище сменились защитники.":"Vitória contabilizada, mas durante a batalha os defensores do Kapishche mudaram.",
"«Достойно, Ловчий», — {0} склоняет голову. Капище «{1}» освящено тобой до конца дня.":"“Muito digno, Caçador”, {0} inclina a cabeça. O Kapishche “{1}” foi consagrado por você até o fim do dia.",
