"Поражение":"Derrota",
"«Приходи, когда окрепнешь», — говорит {0}. Попробуй другую команду: смотри на стихии хранителя и береги щиты для его приёмов.":"“Volte quando estiver mais forte”, diz {0}. Tente outra equipe: observe os elementos do guardião e guarde os escudos para os golpes dele.",
