"Рейтинг зависит от соперника: победа над сильным даёт много, над слабым — мало; поражение от слабого стоит дороже. В твоей лиге победа над равным — +{0}, поражение — −{1}; чем выше лига, тем медленнее подъём. Из лиги можно выпасть. Награду за лигу дают один раз за сезон. В начале нового сезона рейтинг сверх {2} срезается наполовину, а за высшую лигу прошлого сезона Орден дарит сундук. В лигах «{3}», «{4}» и «{5}» — ещё и амулет.":"O ranking depende do rival: vencer um forte dá muito, um fraco — pouco; perder para um fraco custa mais. Na sua liga, vitória sobre um igual — +{0}, derrota — −{1}; quanto mais alta a liga, mais lenta a subida. Dá para cair de liga. A recompensa da liga é dada uma vez por temporada. No início da nova temporada, o ranking acima de {2} é cortado pela metade, e pela liga mais alta da temporada passada a Ordem dá um baú. Nas ligas “{3}”, “{4}” e “{5}” — também um amuleto.",
