"Бросай оберег, когда кольцо сжимается: «Отлично!» даёт больше опыта и шанс поимки.":"Jogue o talismã quando o anel encolher: um “Ótimo!” dá mais XP e mais chance de captura.",
"Родники наполняются снова через несколько минут — прогулка по кругу приносит припасы.":"As fontes recarregam em alguns minutos — uma volta no quarteirão rende suprimentos.",
"Спутник ходит с тобой и находит эссенцию своего семейства.":"O parceiro caminha com você e encontra essência da família dele.",
"В Лиге дерутся живые Ловчие: победа над сильным соперником даёт больше рейтинга, чем над слабым.":"Na Liga lutam Caçadores reais: vencer um rival forte dá mais ranking do que vencer um fraco.",
"Разломы открываются у Капищ каждый час: собери команду из трёх духов.":"As fendas abrem junto aos Kapishches a cada hora: monte uma equipe de três espíritos.",
"Сияющие духи редки — их выдают искры вокруг.":"Espíritos brilhantes são raros — as faíscas ao redor os denunciam.",
"Коконы греются шагами: одновременно можно греть три.":"Os casulos são chocados com passos: dá para chocar três ao mesmo tempo.",
"Ходи джойстиком: лёгкий наклон — шаг, до упора — бег. Километры для коконов считаются так же.":"Ande com o joystick: leve inclinação é caminhar, até o fim é correr. Os quilômetros contam para os casulos do mesmo jeito.",
"Атлас мира переносит в любой уголок Земли раз в полчаса, а Врата Перепутицы — сразу.":"O Atlas do mundo leva você a qualquer canto da Terra a cada meia hora — os Portões do Grande Emaranhado, na hora.",
"Задания дня обновляются в полночь, а за все три ждёт Сундук дня.":"As missões do dia renovam à meia-noite, e por completar as três você ganha o Baú do dia.",
"Поставь защитника на Капище своего клана — он принесёт искры.":"Coloque um defensor no Kapishche do seu clã — ele vai trazer faíscas.",
"Погода усиливает духов своей стихии: в дождь чаще встречаются водные.":"O clima fortalece espíritos do seu elemento: na chuva aparecem mais espíritos de água.",
