"Можно перейти в ту учётную запись — тогда текущий гостевой прогресс на этом устройстве останется в прежней учётной записи, вернуться в неё будет нельзя. Или привязать этот вход к текущему Ловчему.":"Você pode ir para essa conta — o progresso de convidado deste aparelho fica na conta antiga e não dá para voltar. Ou vincular este login ao seu Caçador atual.",
"Можно перейти в ту учётную запись — текущий прогресс останется в своей. Или привязать этот вход к текущему Ловчему.":"Você pode ir para essa conta — o progresso atual fica na sua. Ou vincular este login ao seu Caçador atual.",
