"За день опыт идёт полностью до {0}, дальше до {1} — вполовину, сверх — на четверть. Обучение и знаки Ордена дают опыт всегда полностью. За каждый день без игры копится опыт отдыха ({2}, не больше чем за {3} {4}): пока он есть, опыт вдвое.":"Por dia, o XP vem integral até {0}, depois até {1} pela metade, e acima disso um quarto. O tutorial e as insígnias da Ordem sempre dão XP integral. A cada dia sem jogar acumula XP de descanso ({2}, no máximo por {3} {4}): enquanto houver, o XP vale o dobro.",
"Звание «{0}»":"Título “{0}”",
