"дальше: {0} на {1}":"a seguir: {0} no nível {1}",
"Опыт дают поимки, родники, разломы, капища и задания. С уровнем растут и твои духи: их можно усиливать до уровня Ловчего +5.":"XP vem de capturas, fontes, fendas, Kapishches e missões. Com o nível, seus espíritos também crescem: dá para fortalecê-los até o nível do Caçador +5.",
"С {0} уровня духов можно пробуждать: каждая звезда поднимает предел уровня духа ещё на {1}, до {2}.":"A partir do nível {0}, os espíritos podem ser despertados: cada estrela eleva o limite de nível em mais {1}, até {2}.",
"Ищу настоящие места вокруг — Родники и Капища появятся через несколько секунд":"Procurando lugares reais por perto — Fontes e Kapishches vão aparecer em alguns segundos",
"Посылка из Ордена":"Encomenda da Ordem",
"Поблизости пока нет ни одного Родника, поэтому Орден раз в день присылает припасы: {0}.":"Ainda não há nenhuma Fonte por perto, então a Ordem envia suprimentos uma vez por dia: {0}.",
"Знаешь интересное место рядом? Предложи его в «Меню → Места» — после проверки там появится Родник.":"Conhece um lugar interessante por perto? Sugira-o em “Menu → Lugares” — após a verificação, uma Fonte vai aparecer lá.",
"Спасибо":"Obrigado",
"На проверке":"Em análise",
"Одобрено":"Aprovado",
"Отклонено":"Recusado",
"Родники и Капища стоят у настоящих мест. Знаешь интересный объект рядом? Предложи его!":"Fontes e Kapishches ficam em lugares reais. Conhece um ponto interessante por perto? Sugira!",
"<b>Подходят:</b> памятники, скульптуры, фонтаны, мозаики, необычные здания, храмы, парки, родники, смотровые площадки.":"<b>Servem:</b> monumentos, esculturas, chafarizes, mosaicos, prédios incomuns, templos, parques, nascentes, mirantes.",
"<b>Не подходят:</b> частные дома и дворы, школы и детские сады, опасные места (проезжая часть, стройки), обычные магазины.":"<b>Não servem:</b> casas e quintais particulares, escolas e creches, lugares perigosos (pistas, obras), lojas comuns.",
"Стой рядом с объектом: снимок получает геометку, модератор сверяет её с точкой на карте.":"Fique perto do local: a foto recebe a geolocalização, e o moderador a compara com o ponto no mapa.",
"Сфотографировать объект":"Fotografar o local",
"Предлагать места можно с {0} уровня Ловчего.":"Dá para sugerir lugares a partir do nível {0} de Caçador.",
"Не больше 5 заявок в сутки.":"No máximo 5 sugestões por dia.",
