"Родник — для любого интересного объекта. Капище — для заметных мест: памятник, парк, крупное здание.":"Fonte — para qualquer ponto interessante. Kapishche — para lugares marcantes: monumento, parque, prédio grande.",
"Точка объекта":"Ponto do local",
