"Перепутица спутала дороги мира, и Орден Оберега открыл Ловчим Врата: выбери в Атласе мира любой уголок Земли — там и начнёшь охоту. По карте ходи джойстиком, а в новые края шагай через Атлас. Настоящее местоположение телефона игре не нужно. Прогресс хранится на сервере игры и доступен только тебе; сервер проверяет каждое действие, поэтому нужен интернет. Места на карте и погода загружаются для выбранного района у OpenStreetMap и Open-Meteo (погоду можно выключить в настройках).":"O Grande Emaranhado embaralhou os caminhos do mundo, e a Ordem do Talismã abriu os Portões aos Caçadores: escolha no Atlas do mundo qualquer canto da Terra — é lá que sua caçada começa. Ande pelo mapa com o joystick e vá a novas terras pelo Atlas. O jogo não precisa da localização real do seu celular. Seu progresso fica no servidor do jogo e só você tem acesso; o servidor confere cada ação, por isso é preciso internet. Os lugares do mapa e o clima da área escolhida vêm do OpenStreetMap e do Open-Meteo (o clima pode ser desligado nas configurações).",
